 23 | /**
 24 |  * Split a command string into argv without invoking a shell. Supports single/
 25 |  * double quotes and backslash escapes, but the fixtures only use simple,
 26 |  * whitespace-separated commands ("python3 main.py", "gcc -Wall -O0 main.c -o main", "./main").
 27 |  */
 28 | function tokenize(command: string): string[] {
 29 |   const tokens: string[] = [];
 30 |   let current = "";
 31 |   let quote: "'" | '"' | null = null;
 32 | 
 33 |   for (let i = 0; i < command.length; i++) {
 34 |     const ch = command[i];
 35 |     if (quote) {
 36 |       if (ch === quote) {
 37 |         quote = null;
 38 |       } else {
 39 |         current += ch;
 40 |       }
 41 |     } else if (ch === '"' || ch === "'") {
 42 |       quote = ch;
 43 |     } else if (ch === "\\" && i + 1 < command.length) {
 44 |       current += command[i + 1];
 45 |       i += 1;
 46 |     } else if (/\s/.test(ch)) {
 47 |       if (current) {
 48 |         tokens.push(current);
 49 |         current = "";
 50 |       }
 51 |     } else {
 52 |       current += ch;
 53 |     }
 54 |   }
 55 | 
 56 |   if (current) tokens.push(current);
 57 |   return tokens;
 58 | }
