 60 | function killProcessTree(child: ChildProcess): void {
 61 |   if (child.pid === undefined) return;
 62 |   try {
 63 |     // detached:true makes the child its own process-group leader on POSIX,
 64 |     // so killing the group reaps any grandchildren too.
 65 |     if (process.platform !== "win32") {
 66 |       process.kill(-child.pid, "SIGKILL");
 67 |     } else {
 68 |       child.kill("SIGKILL");
 69 |     }
 70 |   } catch {
 71 |     try {
 72 |       child.kill("SIGKILL");
 73 |     } catch {
 74 |       /* already gone */
 75 |     }
 76 |   }
 77 | }
 78 | 
 79 | function spawnCommand(command: string, config: SpawnConfig): Promise<SpawnOutcome> {
 80 |   const tokens = tokenize(command);
 81 |   if (tokens.length === 0) {
 82 |     return Promise.resolve({ stdout: "", stderr: "empty command", exitCode: null, timedOut: false });
 83 |   }
 84 | 
 85 |   const [cmd, ...args] = tokens;
 86 | 
 87 |   return new Promise((resolve) => {
 88 |     let stdout = "";
 89 |     let stderr = "";
 90 |     let exitCode: number | null = null;
 91 |     let timedOut = false;
 92 |     let settled = false;
 93 | 
 94 |     const child = spawn(cmd, args, {
 95 |       cwd: config.cwd,
 96 |       env: process.env,
 97 |       stdio: ["pipe", "pipe", "pipe"],
 98 |       detached: process.platform !== "win32",
 99 |     });
100 | 
101 |     const append = (target: "stdout" | "stderr", chunk: Buffer) => {
102 |       const text = chunk.toString("utf8");
103 |       if (target === "stdout") {
104 |         const space = config.maxOutputBytes - stdout.length;
105 |         if (space > 0) stdout += text.slice(0, space);
106 |       } else {
107 |         const space = config.maxOutputBytes - stderr.length;
108 |         if (space > 0) stderr += text.slice(0, space);
109 |       }
110 |     };
111 | 
112 |     const finish = () => {
113 |       if (settled) return;
114 |       settled = true;
115 |       clearTimeout(timer);
116 |       resolve({ stdout, stderr, exitCode, timedOut });
117 |     };
118 | 
119 |     const timer = setTimeout(() => {
120 |       timedOut = true;
121 |       killProcessTree(child);
122 |       finish();
123 |     }, config.timeoutMs);
124 | 
125 |     child.stdout?.on("data", (d: Buffer) => append("stdout", d));
126 |     child.stderr?.on("data", (d: Buffer) => append("stderr", d));
127 | 
128 |     child.once("error", (err) => {
129 |       stderr += `\n[runner] failed to spawn '${cmd}': ${err.message}`;
130 |       finish();
131 |     });
132 | 
133 |     child.once("exit", (code) => {
134 |       exitCode = code;
135 |       finish();
136 |     });
137 | 
138 |     child.stdin?.on("error", () => {
139 |       /* ignore EPIPE if the process exited before reading stdin */
140 |     });
141 | 
142 |     if (config.input !== undefined) {
143 |       child.stdin?.write(config.input);
144 |     }
145 |     child.stdin?.end();
146 |   });
147 | }
