157 | export async function runAssignment(
158 |   assignment: Assignment,
159 |   code: string,
160 |   options: RunnerOptions = {},
161 | ): Promise<RunResult> {
162 |   const runTimeoutMs = options.runTimeoutMs ?? RUN_TIMEOUT_MS;
163 |   const buildTimeoutMs = options.buildTimeoutMs ?? BUILD_TIMEOUT_MS;
164 |   const maxOutputBytes = options.maxOutputBytes ?? MAX_OUTPUT_BYTES;
165 | 
166 |   const sandboxDir = fs.mkdtempSync(path.join(os.tmpdir(), "hintlab-"));
167 |   const sourceFile = assignment.language === "python" ? "main.py" : "main.c";
168 | 
169 |   fs.writeFileSync(path.join(sandboxDir, sourceFile), code, "utf8");
170 |   fs.writeFileSync(
171 |     path.join(sandboxDir, "tests.json"),
172 |     JSON.stringify(
173 |       {
174 |         assignmentId: assignment.assignmentId,
175 |         language: assignment.language,
176 |         statement: assignment.statement,
177 |         ...(assignment.build ? { build: assignment.build } : {}),
178 |         run: assignment.run,
179 |         tests: assignment.tests,
180 |       },
181 |       null,
182 |       2,
183 |     ),
184 |     "utf8",
185 |   );
186 | 
187 |   let build: BuildResult | null = null;
188 |   if (assignment.build) {
189 |     const b = await spawnCommand(assignment.build, {
190 |       cwd: sandboxDir,
191 |       timeoutMs: buildTimeoutMs,
192 |       maxOutputBytes,
193 |     });
194 |     build = {
195 |       ok: !b.timedOut && b.exitCode === 0,
196 |       stdout: b.stdout,
197 |       stderr: b.stderr,
198 |       timedOut: b.timedOut,
199 |     };
200 | 
201 |     if (!build.ok) {
202 |       if (options.cleanup) cleanupSandbox(sandboxDir);
203 |       return {
204 |         assignmentId: assignment.id,
205 |         sandboxDir,
206 |         build,
207 |         tests: [],
208 |         passed: 0,
209 |         failed: 0,
210 |         total: 0,
211 |       };
212 |     }
213 |   }
214 | 
215 |   const tests: TestResult[] = [];
216 |   for (const test of assignment.tests) {
217 |     const r = await spawnCommand(assignment.run, {
218 |       cwd: sandboxDir,
219 |       input: test.input,
220 |       timeoutMs: runTimeoutMs,
221 |       maxOutputBytes,
222 |     });
223 |     const got = r.stdout.trim();
224 |     const passed = !r.timedOut && r.exitCode === 0 && got === test.expected;
225 |     tests.push({
226 |       name: test.name,
227 |       input: test.input,
228 |       expected: test.expected,
229 |       got,
230 |       stderr: r.stderr,
231 |       exitCode: r.exitCode,
232 |       timedOut: r.timedOut,
233 |       passed,
234 |     });
235 |   }
236 | 
237 |   const passed = tests.filter((t) => t.passed).length;
238 | 
239 |   if (options.cleanup) cleanupSandbox(sandboxDir);
240 | 
241 |   return {
242 |     assignmentId: assignment.id,
243 |     sandboxDir,
244 |     build,
245 |     tests,
246 |     passed,
247 |     failed: tests.length - passed,
248 |     total: tests.length,
249 |   };
250 | }
