 41 | const GIVE_HINT_DESCRIPTION = [
 42 |   "Show the student exactly one hint at the requested level.",
 43 |   "level 1 = a conceptual nudge; level 2 = point to the area or line of the bug;",
 44 |   "level 3 = a near-explicit explanation of the bug and the underlying concept.",
