 49 | /**
 50 |  * The shared give_hint tool. It is the only hint sink: the server-side guard runs
 51 |  * here before a hint is recorded, and a rejected hint becomes a tool error so the
 52 |  * model rephrases instead of the hint reaching the student.
 53 |  */
 54 | const giveHintTool = createTool({
 55 |   name: "give_hint",
 56 |   description: GIVE_HINT_DESCRIPTION,
 57 |   inputSchema: z.object({
 58 |     level: z.number().int().min(1).max(3),
 59 |     tag: z.string().optional(),
 60 |     text: z.string(),
 61 |   }),
 62 |   async execute(input, context) {
 63 |     const session = context.sessionId ? getSession(context.sessionId) : undefined;
 64 |     const wanted = session?.currentHintLevel ?? input.level;
 65 | 
 66 |     if (session && input.level !== wanted) {
 67 |       emitEvent(session, "hint_rejected", {
 68 |         level: input.level,
 69 |         wantedLevel: wanted,
 70 |         reason: "wrong level",
 71 |       });
 72 |       throw new Error(
 73 |         `You were asked for a level ${wanted} hint, but called give_hint with level ${input.level}. ` +
 74 |           `Call give_hint again with level ${wanted}.`,
 75 |       );
 76 |     }
 77 | 
 78 |     if (session && session.hints.some((h) => h.level === input.level)) {
 79 |       // This level was already delivered; tell the model to stop without erroring,
 80 |       // so it finishes its turn instead of retrying forever.
 81 |       return {
 82 |         shown: false,
 83 |         alreadyDelivered: true,
 84 |         message: `The level ${input.level} hint was already delivered. Do not call give_hint again; finish your turn.`,
 85 |       };
 86 |     }
 87 | 
 88 |     const guard = checkHint(input.text);
 89 |     if (!guard.ok) {
 90 |       if (session) {
 91 |         emitEvent(session, "hint_rejected", { level: input.level, reason: guard.reason, text: input.text });
 92 |       }
 93 |       throw new Error(
 94 |         `HintLab rejected this hint: ${guard.reason}. Rephrase the hint in plain prose with no code, ` +
 95 |           `then call give_hint again.`,
 96 |       );
 97 |     }
 98 | 
 99 |     const hint = {
100 |       level: input.level as 1 | 2 | 3,
101 |       tag: input.tag,
102 |       text: input.text,
103 |       at: new Date().toISOString(),
104 |     };
105 |     if (session) {
106 |       recordHint(session, hint);
107 |     }
108 |     return { shown: true, level: input.level };
109 |   },
110 | });
