128 | function capabilities() {
129 |   return {
130 |     requestToolApproval: async (req: {
131 |       sessionId: string;
132 |       toolName: string;
133 |       toolCallId: string;
134 |       input: unknown;
135 |     }) => {
136 |       const session = getSession(req.sessionId);
137 |       const commands = extractCommands(req.input);
138 | 
139 |       if (req.toolName !== "run_commands") {
140 |         const reason = `tool "${req.toolName}" requires approval and is not allowed in HintLab`;
141 |         if (session) {
142 |           emitEvent(session, "approval", {
143 |             toolName: req.toolName,
144 |             toolCallId: req.toolCallId,
145 |             commands,
146 |             allowed: false,
147 |             reason,
148 |           });
149 |         }
150 |         return { approved: false, reason };
151 |       }
152 | 
153 |       const decision = allowCommands(commands);
154 |       if (session) {
155 |         emitEvent(session, "approval", {
156 |           toolName: req.toolName,
157 |           toolCallId: req.toolCallId,
158 |           commands,
159 |           allowed: decision.allowed,
160 |           reason: decision.reason,
161 |         });
162 |       }
163 |       return decision.allowed
164 |         ? { approved: true }
165 |         : { approved: false, reason: decision.reason ?? "command not on the HintLab allow-list" };
166 |     },
167 |   };
168 | }
