170 | /** Map the raw SDK events to HintLab SSE events, routed by session id. */
171 | function handleCoreEvent(e: {
172 |   type: string;
173 |   payload?: { sessionId?: string; event?: Record<string, unknown>; [k: string]: unknown };
174 | }): void {
175 |   const sessionId = e.payload?.sessionId;
176 |   if (!sessionId) return;
177 |   const session = getSession(sessionId);
178 |   if (!session) return;
179 | 
180 |   if (e.type === "agent_event") {
181 |     const ev = e.payload?.event as Record<string, unknown> | undefined;
182 |     if (!ev) return;
183 |     switch (ev.type) {
184 |       case "content_start":
185 |         if (ev.contentType === "tool") {
186 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, input: ev.input });
187 |         } else if (ev.contentType === "text") {
188 |           emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "start" });
189 |         } else if (ev.contentType === "reasoning") {
190 |           emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted });
191 |         }
192 |         break;
193 |       case "content_update":
194 |         if (ev.contentType === "tool") {
195 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, update: ev.update });
196 |         }
197 |         break;
198 |       case "content_end":
199 |         if (ev.contentType === "tool") {
200 |           emitEvent(session, "tool_result", {
201 |             toolName: ev.toolName,
202 |             toolCallId: ev.toolCallId,
203 |             output: ev.output,
204 |             error: ev.error,
205 |             durationMs: ev.durationMs,
206 |           });
207 |         } else if (ev.contentType === "text") {
208 |           emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "end" });
209 |         } else if (ev.contentType === "reasoning") {
210 |           emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted, phase: "end" });
211 |         }
212 |         break;
213 |       case "iteration_start":
214 |         emitEvent(session, "status", { iteration: ev.iteration, phase: "iteration_start" });
215 |         break;
216 |       case "iteration_end":
217 |         emitEvent(session, "status", { iteration: ev.iteration, toolCallCount: ev.toolCallCount, phase: "iteration_end" });
218 |         break;
219 |       case "usage":
220 |         emitEvent(session, "status", {
221 |           usage: {
222 |             inputTokens: ev.inputTokens,
223 |             outputTokens: ev.outputTokens,
224 |             totalInputTokens: ev.totalInputTokens,
225 |             totalOutputTokens: ev.totalOutputTokens,
226 |           },
227 |         });
228 |         break;
229 |       case "notice":
230 |         emitEvent(session, "status", { noticeType: ev.noticeType, message: ev.message });
231 |         break;
232 |       case "done":
233 |         emitEvent(session, "done", { reason: ev.reason, text: ev.text, iterations: ev.iterations });
234 |         break;
235 |       case "error":
236 |         emitEvent(session, "error", {
237 |           message: ev.error instanceof Error ? ev.error.message : String(ev.error),
238 |           recoverable: ev.recoverable,
239 |           iteration: ev.iteration,
240 |         });
241 |         break;
242 |       default:
243 |         break;
244 |     }
245 |     return;
246 |   }
247 | 
248 |   if (e.type === "status") {
249 |     emitEvent(session, "status", { status: e.payload?.status });
250 |   } else if (e.type === "ended") {
251 |     emitEvent(session, "done", { reason: e.payload?.reason });
252 |   } else if (e.type === "hook") {
253 |     const payload = e.payload as Record<string, unknown>;
254 |     emitEvent(session, "status", { hook: payload.hookEventName, toolName: payload.toolName });
255 |   }
256 | }
