322 | /** Run the first (level-1) agent turn in the background for a session. */
323 | export async function startSession(sessionId: string): Promise<void> {
324 |   const session = getSession(sessionId);
325 |   if (!session) return;
326 | 
327 |   const mainFile = session.language === "python" ? "main.py" : "main.c";
328 |   const mainPath = path.resolve(session.workdir, mainFile);
329 |   const testsPath = path.resolve(session.workdir, "tests.json");
330 | 
331 |   const cline = await getCline();
332 |   session.busy = true;
333 |   setStatus(session, "running");
334 | 
335 |   try {
336 |     const result = await cline.start({
337 |       interactive: true,
338 |       prompt: buildFirstPrompt(session, mainPath, testsPath),
339 |       config: {
340 |         sessionId: session.id,
341 |         providerId: HINTLAB_PROVIDER_ID,
342 |         modelId: HINTLAB_MODEL_ID,
343 |         temperature: 0,
344 |         systemPrompt: SYSTEM_PROMPT,
345 |         cwd: session.workdir,
346 |         workspaceRoot: session.workdir,
347 |         enableTools: true,
348 |         enableSpawnAgent: false,
349 |         enableAgentTeams: false,
350 |         extraTools: [giveHintTool as unknown as AgentTool],
351 |       },
352 |       toolPolicies: toolPolicies(),
353 |       capabilities: capabilities(),
354 |     });
355 | 
356 |     session.agentSessionId = result.sessionId;
357 |     registerAgentSession(result.sessionId, session.id);
358 |     const finishReason = (result.result as { finishReason?: string } | undefined)?.finishReason;
359 |     emitEvent(session, "status", { message: "initial agent turn finished", finishReason });
360 |   } catch (err) {
361 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
362 |     setStatus(session, "error");
363 |   } finally {
364 |     session.busy = false;
365 |     if (session.status !== "error") {
366 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
367 |     }
368 |   }
369 | }
