371 | /** Ask the agent for the next hint level (2, then 3). Returns after the turn completes. */
372 | export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
373 |   const session = getSession(sessionId);
374 |   if (!session) throw Object.assign(new Error("unknown session"), { status: 404 });
375 |   if (session.busy) throw Object.assign(new Error("agent is still busy"), { status: 409 });
376 |   if (session.hints.length >= 3) {
377 |     return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
378 |   }
379 | 
380 |   const nextLevel = Math.min(session.hints.length + 1, 3);
381 |   session.currentHintLevel = nextLevel;
382 |   session.busy = true;
383 |   setStatus(session, "running");
384 | 
385 |   const cline = await getCline();
386 |   try {
387 |     const result = await cline.send({
388 |       sessionId: session.agentSessionId ?? session.id,
389 |       prompt: buildNextPrompt(session, nextLevel),
390 |     });
391 |     const finishReason = (result as { finishReason?: string } | undefined)?.finishReason;
392 |     emitEvent(session, "status", { message: `level ${nextLevel} agent turn finished`, finishReason });
393 |   } catch (err) {
394 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
395 |     setStatus(session, "error");
396 |   } finally {
397 |     session.busy = false;
398 |     if (session.status !== "error") {
399 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
400 |     }
401 |   }
402 | 
403 |   return { level: nextLevel, status: session.status };
404 | }
