  8 | /** In-memory session store, keyed by HintLab session id. */
  9 | const sessions = new Map<string, Session>();
 10 | 
 11 | /** Reverse index: SDK agent session id -> HintLab session id. */
 12 | const agentIdIndex = new Map<string, string>();
 13 | 
 14 | type StopAgentHook = (agentSessionId: string) => void;
 15 | let stopAgentHook: StopAgentHook | null = null;
