 30 | export function createSession(input: CreateSessionInput): Session {
 31 |   const now = Date.now();
 32 |   const session: Session = {
 33 |     id: randomUUID(),
 34 |     assignmentId: input.assignmentId,
 35 |     language: input.language,
 36 |     statement: input.statement,
 37 |     workdir: input.workdir,
 38 |     testResults: input.testResults,
 39 |     hints: [],
 40 |     events: [],
 41 |     status: "created",
 42 |     busy: false,
 43 |     currentHintLevel: 1,
 44 |     sseClients: new Set(),
 45 |     createdAt: now,
 46 |     lastActiveAt: now,
 47 |   };
 48 |   sessions.set(session.id, session);
 49 |   return session;
 50 | }
