 52 | /** Look up a session by HintLab id or by the SDK's agent session id. */
 53 | export function getSession(id: string): Session | undefined {
 54 |   const direct = sessions.get(id);
 55 |   if (direct) return direct;
 56 |   const hintlabId = agentIdIndex.get(id);
 57 |   return hintlabId ? sessions.get(hintlabId) : undefined;
 58 | }
 59 | 
 60 | export function registerAgentSession(agentSessionId: string, hintlabSessionId: string): void {
 61 |   agentIdIndex.set(agentSessionId, hintlabSessionId);
 62 | }
 63 | 
 64 | /** Record an event and broadcast it to every connected SSE client. */
 65 | export function emitEvent(session: Session, name: string, data: unknown): void {
 66 |   const event: SessionEvent = { name, data, at: Date.now() };
 67 |   session.events.push(event);
 68 |   session.lastActiveAt = Date.now();
 69 |   for (const res of session.sseClients) {
 70 |     try {
 71 |       writeSse(res, name, data);
 72 |     } catch {
 73 |       /* client already gone */
 74 |     }
 75 |   }
 76 | }
 77 | 
 78 | /** Set the session status (emits a `status` event on change). */
 79 | export function setStatus(session: Session, status: string): void {
 80 |   if (session.status === status) return;
 81 |   session.status = status;
 82 |   session.lastActiveAt = Date.now();
 83 |   emitEvent(session, "status", { status });
 84 | }
 85 | 
 86 | /** Register an SSE client and replay the buffered event history to it. */
 87 | export function addClient(session: Session, res: Response): void {
 88 |   session.sseClients.add(res);
 89 |   session.lastActiveAt = Date.now();
 90 |   // Replay is synchronous and single-threaded, so no event can be broadcast
 91 |   // between the snapshot below and the live broadcast that follows it.
 92 |   for (const event of session.events) {
 93 |     try {
 94 |       writeSse(res, event.name, event.data);
 95 |     } catch {
 96 |       break;
 97 |     }
 98 |   }
 99 | }
100 | 
101 | export function removeClient(session: Session, res: Response): void {
102 |   session.sseClients.delete(res);
103 | }
104 | 
105 | export function recordHint(session: Session, hint: Hint): void {
106 |   session.hints.push(hint);
107 |   session.lastActiveAt = Date.now();
108 |   emitEvent(session, "hint", hint);
109 | }
110 | 
111 | /** Remove a session, close its clients, and delete its temp workdir. */
112 | export function deleteSession(id: string): void {
113 |   const session = getSession(id);
114 |   if (!session) return;
115 |   sessions.delete(session.id);
116 |   if (session.agentSessionId) agentIdIndex.delete(session.agentSessionId);
117 | 
118 |   for (const res of session.sseClients) {
119 |     try {
120 |       res.end();
121 |     } catch {
122 |       /* ignore */
123 |     }
124 |   }
125 |   session.sseClients.clear();
126 | 
127 |   if (session.workdir) {
128 |     try {
129 |       fs.rmSync(session.workdir, { recursive: true, force: true });
130 |     } catch {
131 |       /* best-effort */
132 |     }
133 |   }
134 | 
135 |   if (session.agentSessionId) {
136 |     try {
137 |       stopAgentHook?.(session.agentSessionId);
138 |     } catch {
139 |       /* ignore */
140 |     }
141 |   }
142 | }
143 | 
144 | /** Start the TTL cleanup loop. Unref'd so it never keeps the process alive. */
145 | export function startCleanupLoop(): void {
146 |   const timer = setInterval(() => {
147 |     const now = Date.now();
148 |     for (const session of [...sessions.values()]) {
149 |       if (now - session.lastActiveAt > SESSION_TTL_MS) {
150 |         deleteSession(session.id);
151 |       }
152 |     }
153 |   }, SESSION_CLEANUP_INTERVAL_MS);
154 |   timer.unref();
155 | }

