 95 | async function waitUntil(fn: () => boolean, what: string, timeoutMs: number): Promise<void> {
 96 |   const deadline = Date.now() + timeoutMs;
 97 |   while (Date.now() < deadline) {
 98 |     if (fn()) return;
 99 |     await new Promise((r) => setTimeout(r, 100));
100 |   }
101 |   throw new Error(`timeout waiting for ${what}`);
102 | }
