109 | // Independent code markers (beyond the guard) used to re-verify hints contain no code.
110 | function hasCodeMarker(text: string): boolean {
111 |   if (text.includes("```")) return true;
112 |   return /(?:\bdef\s+\w+\s*\(|\bprint\s*\(|\bprintf\s*\(|\bscanf\s*\(|\brange\s*\(|\blen\s*\(|\bsum\s*\(|\bfor\s+\w+\s+in\s|\bwhile\s*\(|\bif\s*\(|\(float\)|\(int\)|;\s*$)/.test(
113 |     text,
114 |   );
115 | }
