151 |     check(res.status === 200, `SSE stream -> 200 (got ${res.status})`);
152 |     if (!res.body) return;
153 |     const reader = res.body.getReader();
154 |     const decoder = new TextDecoder();
155 |     let buffer = "";
156 |     try {
157 |       for (;;) {
158 |         const { done, value } = await reader.read();
159 |         if (done) break;
160 |         buffer += decoder.decode(value, { stream: true });
161 |         let idx: number;
162 |         while ((idx = buffer.indexOf("\n\n")) >= 0) {
163 |           const block = buffer.slice(0, idx);
164 |           buffer = buffer.slice(idx + 2);
165 |           let name = "message";
166 |           const dataLines: string[] = [];
167 |           for (const line of block.split("\n")) {
168 |             if (line.startsWith(":")) continue;
169 |             if (line.startsWith("event:")) name = line.slice(6).trim();
170 |             else if (line.startsWith("data:")) dataLines.push(line.slice(5).trimStart());
171 |           }
172 |           if (dataLines.length === 0) continue;
173 |           let data: unknown;
174 |           try {
175 |             data = JSON.parse(dataLines.join("\n"));
